### 3.1 Connection Pool Configuration

```python
import redis.asyncio as redis
from redis.asyncio.connection import ConnectionPool

class OptimizedRedisPool:
    """Optimized Redis connection pool configuration"""

    def __init__(self, redis_url: str, environment: str):
        # Environment-specific pool sizes
        pool_configs = {
            'development': {'max_connections': 10, 'retry_on_timeout': True},
            'staging': {'max_connections': 50, 'retry_on_timeout': True},
            'production': {'max_connections': 100, 'retry_on_timeout': True}
        }

        config = pool_configs.get(environment, pool_configs['development'])

        self.pool = ConnectionPool.from_url(
            redis_url,
            max_connections=config['max_connections'],
            retry_on_timeout=config['retry_on_timeout'],
            socket_keepalive=True,
            socket_keepalive_options={
                1: 1,  # TCP_KEEPIDLE
                2: 3,  # TCP_KEEPINTVL
                3: 5,  # TCP_KEEPCNT
            },
            socket_connect_timeout=5,
            socket_timeout=5,
            health_check_interval=60
        )

    def get_redis_client(self) -> redis.Redis:
        """Get Redis client with optimized configuration"""
        return redis.Redis(
            connection_pool=self.pool,
            decode_responses=True,
            socket_keepalive=True,
            socket_keepalive_options={1: 1, 2: 3, 3: 5}
        )
