class OptimizedKeyPatterns:
    """Optimized Redis key design patterns"""

    @staticmethod
    def user_session_key(tenant_id: str, user_id: str, session_id: str) -> str:
        """Optimized session key with consistent hashing"""
        return f"session:{tenant_id}:{user_id}:{session_id}"

    @staticmethod
    def cache_key(tenant_id: str, cache_type: str, identifier: str) -> str:
        """Optimized cache key with TTL implications"""
        return f"cache:{tenant_id}:{cache_type}:{identifier}"

    @staticmethod
    def queue_stream_key(tenant_id: str, service: str, queue_type: str) -> str:
        """Optimized stream key for message queues"""
        return f"queue:{tenant_id}:{service}:{queue_type}"

class DataStructureOptimizer:
    """Optimize Redis data structures for performance"""

    def __init__(self, redis_client: redis.Redis):
        self.redis = redis_client

    async def optimize_hash_fields(self, key: str, data: Dict[str, Any]) -> None:
        """Optimize hash storage with field compression"""
        # Use HSET with multiple field-value pairs
        if len(data) > 1:
            await self.redis.hset(key, mapping=data)
        else:
            # Single field - use HSET
            field, value = next(iter(data.items()))
            await self.redis.hset(key, field, value)

    async def optimize_list_operations(self, key: str, items: List[str],
                                     operation: str = "append") -> None:
        """Optimize list operations with batching"""
        if operation == "append":
            # Use RPUSH for multiple items
            if items:
                await self.redis.rpush(key, *items)
        elif operation == "prepend":
            # Use LPUSH for multiple items
            if items:
                await self.redis.lpush(key, *items)

    async def optimize_set_operations(self, key: str, members: List[str]) -> None:
        """Optimize set operations with batching"""
        if members:
            await self.redis.sadd(key, *members)
