async def run_benchmark_suite(redis_url: str) -> Dict[str, Any]:
    """Run standard benchmark suite"""
    tester = RedisLoadTester(redis_url)

    # Standard test configuration
    test_configs = {
        'light_load': {
            'concurrent_connections': 5,
            'operations_per_test': 1000,
            'data_size': '1KB'
        },
        'moderate_load': {
            'concurrent_connections': 20,
            'operations_per_test': 10000,
            'data_size': '10KB'
        },
        'heavy_load': {
            'concurrent_connections': 50,
            'operations_per_test': 100000,
            'data_size': '100KB'
        }
    }

    benchmark_results = {}
    for load_type, config in test_configs.items():
        print(f"Running {load_type} benchmark...")
        benchmark_results[load_type] = await tester.run_load_test(config)

    return benchmark_results
